      margin-top: 3px;
      font-size: 11.5px;
      line-height: 1.5;
      color: var(--cx-text-faint);
    }
    .cx-set-ctrl {
      flex: none;
      display: flex;
      align-items: center;
      gap: 8px;
      min-width: 132px;
      justify-content: flex-end;
    }
