    .cx-switch:focus-visible { outline: 2px solid var(--cx-blue); outline-offset: 2px; }

    /* 滑块 */
    .cx-range {
      flex: 1;
      min-width: 110px;
      max-width: 190px;
      height: 22px;
      accent-color: var(--cx-blue);
      cursor: pointer;
    }
