    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 18px;
    border-top: 1px solid var(--cx-border-soft);
    font-size: 11.5px;
    color: var(--cx-text-faint);
  }
  .cx-modal-btn {
    font-family: var(--cx-font-ui);
    font-size: 12.5px;
    color: var(--cx-text);
    background: var(--cx-chip-bg);
    border: 1px solid var(--cx-border-strong);
    border-radius: 999px;
    padding: 5px 14px;
    cursor: pointer;
  }
  .cx-modal-btn:hover { background: var(--cx-btn-hover); }
