{"file_path": ".verify-settings.mjs", "content": "/**
 * 临时验证脚本：把 linuxdo-codex.user.js 里真正的设置核心代码抽出来跑，
 * 不是抄一份副本 —— 抄的副本测过了也说明不了源文件的正确性。
 * 跑完即删。
 */
import { readFileSync } from "node:fs";

const SRC = readFileSync(new URL("./linuxdo-codex.user.js", import.meta.url), "utf8");

let pass = 0;
const fails = [];
function ok(name, cond, extra) {
  if (cond) { pass++; return; }
  fails.push(name + (extra !== undefined ? ` — ${JSON.stringify(extra)}` : ""));
}

function slice(startMarker, endMarker) {
  const a = SRC.indexOf(startMarker);
  if (a < 0) throw new Error("start marker not found: " + startMarker);
  const b = SRC.indexOf(endMarker, a);
  if (b < 0) throw new Error("end marker not found: " + endMarker);
  return SRC.slice(a, b);
}

/* ---------- 1. 抽出真实的设置核心 ---------- */
const coreSrc = slice("  const DEFAULTS = {", "  /* ============================== 内联 SVG 图标");
const clampSrc = slice("  function clampPercent(", "  function debounce(").replace(/\}\s*\n\s*$/, "}\n");
const specSrc = slice("  const SETTING_CSS_VAR = {", "  function specItem(key) {");

const CODE_LANGS_STUB = { rust: {}, python: {}, typescript: {}, go: {}, java: {} };
const CODE_LANG_NAMES_STUB = { rust: "Rust", python: "Python", typescript: "TypeScript", go: "Go", java: "Java" };

function makeStore() {
  const map = new Map();
  return {
    getItem: (k) => (map.has(k) ? map.get(k) : null),
    setItem: (k, v) => map.set(k, String(v)),
    removeItem: (k) => map.delete(k),
    _map: map
  };
}

function loadCore(store) {
  // 最小 document stub：applyLayerOpacity / applyPanelWidth 要写 <html> 的 style 与 classList
  const rootStyle = new Map();
  const rootClasses = new Set();
  const doc = {
    documentElement: {
      style: {
        setProperty: (k, v) => rootStyle.set(k, v),
        removeProperty: (k) => rootStyle.delete(k)
      },
      classList: {
        toggle: (c, on) => (on ? rootClasses.add(c) : rootClasses.delete(c)),
        add: (c) => rootClasses.add(c),
        remove: (c) => rootClasses.delete(c),
        contains: (c) => rootClasses.has(c)
      }
    }
  };
  const calls = { visual: 0, syncControls: 0, codePanel: [], applied: [] };
  const stubs = {
    syncCxMode: () => {},
    syncModeBtn: () => {},
    makeFavicon: () => {},
    setCodePanelHidden: (hidden) => calls.codePanel.push(hidden),
    renderCodePanel: () => {},
    rerenderDetailPosts: () => {},
    syncSettingControls: () => { calls.syncControls++; },
    specItem: () => null // pageOpacity 的 min 读不到就退回 0，不影响不透明度主逻辑
  };
  const body = `
    const DIMMED_CLASS = "codex-page-dim";
    ${clampSrc}
    ${coreSrc}
    return { DEFAULTS, SETTINGS_KEY, LEGACY_KEYS, loadSettings, cfg, setCfg, setCfgMany,
             resetSettings, applySettings, applyVisualSettings, applyPanelWidth,
             applyPageOpacity, applyLayerOpacity, STRUCTURAL_KEYS };
  `;
  const names = Object.keys(stubs);
  const fn = new Function("localStorage", "document", ...names, body);
  const api = fn(store, doc, ...names.map((n) => stubs[n]));
  // 计数钩子：替换掉内部 apply 路径不便，改为观察 setCfg 的分支行为
  return { api, rootStyle, rootClasses, calls };
}

const NEW_KEY = "linuxdo-codex:settings";
const LEGACY = {
  theme: "linuxdo-codex-mode",
  railWidth: "linuxdo-codex-rail-w",
  panelWidth: "linuxdo-codex-panel-w",
  codePanel: "linuxdo-codex-code-panel",
  lang: "linuxdo-codex-code-lang",
  codeMode: "linuxdo-codex-code-mode",
  composePreview: "linuxdo-codex-compose-preview"
};

/* ---------- 2. 默认值 ---------- */
{
  const { api } = loadCore(makeStore());
  const expected = {
    theme: "auto", railWidth: 306, panelWidth: 0, threadMaxWidth: 760, codePanel: true,
    lang: "rust", codeMode: "code", pageOpacity: 100, decorations: true,
    quoteCard: true, quoteOpen: false, composePreview: false
  };
  for (const [k, v] of Object.entries(expected)) {
    ok(`默认值 ${k}`, api.cfg(k) === v, { got: api.cfg(k), want: v });
  }
  ok("SETTINGS_KEY 正确", api.SETTINGS_KEY === NEW_KEY, api.SETTINGS_KEY);
  ok("旧键映射齐全", Object.keys(LEGACY).every((k) => api.LEGACY_KEYS[k] === LEGACY[k]));
  ok("STRUCTURAL_KEYS 覆盖装饰三项",
    ["decorations", "quoteCard", "quoteOpen"].every((k) => api.STRUCTURAL_KEYS.has(k)));
}

/* ---------- 3. 旧键迁移（值语义换算） ---------- */
{
  const store = makeStore();
  store.setItem("linuxdo-codex-mode", "dark");
  store.setItem("linuxdo-codex-rail-w", "400");
  store.setItem("linuxdo-codex-panel-w", "520");
  store.setItem("linuxdo-codex-code-panel", "0");   // "0" = 隐藏 → 布尔 false
  store.setItem("linuxdo-codex-code-lang", "python");
  store.setItem("linuxdo-codex-code-mode", "diff");
  store.setItem("linuxdo-codex-compose-preview", "1"); // "1" = 开 → true
