    setCodePanelHidden: () => {}, renderCodePanel: () => {}, rerenderDetailPosts: () => {},
    renderListRows: () => {}, syncSettingControls: () => {}, specItem: () => null
  };
  const names = Object.keys(stubs);
  const body = `
    const RAIL_WIDTH = 306;
    const DIMMED_CLASS = "codex-page-dim";
