  }
  ok("旧键映射齐全", Object.keys(LEGACY).every((k) => api.LEGACY_KEYS[k] === LEGACY[k]));
  ok("列表结构键集合", ["decorations", "listTraceRate", "listThinkingOpen"].every((k) => api.LIST_STRUCTURAL_KEYS.has(k))
    && !api.LIST_STRUCTURAL_KEYS.has("quoteOpen"));
  ok("楼内结构键集合", ["decorations", "quoteCard", "quoteOpen", "detailThinkingOpen"].every((k) => api.DETAIL_STRUCTURAL_KEYS.has(k))
    && !api.DETAIL_STRUCTURAL_KEYS.has("listTraceRate"));
