/* ============ 2. 列表装饰逻辑（真实代码） ============ */
const poolsSrc = slice("  const RUN_LINES = [", "  /** 思考块正文");
const thinkSrc = slice("  function thinkSentences(", "  /** 英文思考块（楼内）");
const listTraceSrc = slice("  function listTraceHtml(", "  function renderListRows() {");
const mulberrySrc = slice("  function mulberry32(", "  const CODE_LANGS = {");

const ICONS_STUB = {
  terminal: "[i:terminal]", file: "[i:file]", search: "[i:search]", folder: "[i:folder]",
  check: "[i:check]", globe: "[i:globe]", branch: "[i:branch]"
};
const escapeHtml = (s) => String(s ?? "").replace(/[&<>"']/g, (c) =>
  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

let SET = { decorations: true, listTraceRate: 46, listThinkingOpen: false, detailThinkingOpen: true };
const cfg = (k) => SET[k];

const deco = new Function("cfg", "ICONS", "escapeHtml",
  mulberrySrc + poolsSrc + thinkSrc + listTraceSrc +
  "\nreturn { listTraceHtml, thinkingHtml, runlineHtmlFor, RUN_LINES, thinkSentences };"
)(cfg, ICONS_STUB, escapeHtml);

const SEP = `<div class="cx-trow-sep"></div>`;
const topics = Array.from({ length: 400 }, (_, i) => ({ id: 100000 + i * 7919 }));
function scan(traceFn) {
  const out = { sep: 0, think: 0, run: 0, other: 0 };
  topics.forEach((t, i) => {
    const { html } = traceFn(t, i, -1);
    if (html === SEP) out.sep++;
    else if (html.startsWith('<div class="cx-think')) out.think++;
    else if (html.startsWith('<div class="cx-runline">')) out.run++;
    else out.other++;
  });
  return out;
}

{
  // 总开关关掉 → 一律普通分隔线（这正是「开启后才生效」的那条路径）
  SET = { decorations: false, listTraceRate: 46, listThinkingOpen: false };
  let r = scan(deco.listTraceHtml);
  ok("decorations=false → 全是分隔线", r.sep === 400 && r.think === 0 && r.run === 0, r);

  // 密度 0 → 同理
  SET = { decorations: true, listTraceRate: 0, listThinkingOpen: false };
  r = scan(deco.listTraceHtml);
  ok("listTraceRate=0 → 全是分隔线", r.sep === 400 && r.think === 0 && r.run === 0, r);

  // 密度 100 → 每条缝都有痕迹，且思考块 / 工具调用行各占一半
  SET = { decorations: true, listTraceRate: 100, listThinkingOpen: false };
  r = scan(deco.listTraceHtml);
  ok("rate=100 → 没有分隔线", r.sep === 0 && r.other === 0, r);
  ok("rate=100 → 痕迹全部是思考块或工具调用行", r.think + r.run === 400, r);
  ok("rate=100 → 思考块约占一半", Math.abs(r.think - 200) <= 40, r);

  // 默认 46%：痕迹比例大致贴合
  SET = { decorations: true, listTraceRate: 46, listThinkingOpen: false };
  r = scan(deco.listTraceHtml);
  const traced = 400 - r.sep;
  ok("rate=46 → 痕迹条数约为 46%", Math.abs(traced / 400 - 0.46) < 0.06, { traced, ...r });
  ok("rate=46 → 未命中的仍是分隔线", r.sep > 0 && r.other === 0, r);

  // 密度单调性：密度越高痕迹越多
  const counts = [0, 20, 46, 80, 100].map((rate) => {
    SET = { decorations: true, listTraceRate: rate, listThinkingOpen: false };
    return 400 - scan(deco.listTraceHtml).sep;
  });
  ok("密度单调不减", counts.every((c, i) => i === 0 || c >= counts[i - 1]), counts);
}

{
  // 稳定性：同一 (话题, 行号) 反复算 → 结果一致（刷新后痕迹不跳）
  SET = { decorations: true, listTraceRate: 100, listThinkingOpen: false };
  const a = deco.listTraceHtml(topics[7], 7, -1).html;
  const b = deco.listTraceHtml(topics[7], 7, -1).html;
  ok("同一行两次结果一致", a === b);
  const other = deco.listTraceHtml(topics[8], 8, -1).html;
  ok("不同行结果不同（按种子铺开）", a !== other);

  // 换种子后重算仍一致，且不受前面调用次数影响（mulberry32 是纯函数）
  const c = deco.listTraceHtml(topics[7], 7, 3).html;
  ok("avoidRun 不影响思考块那条", c === a || a.startsWith('<div class="cx-think'), { a, c });
}

{
  // avoidRun：工具调用行不能和上一行同款
  SET = { decorations: true, listTraceRate: 100, listThinkingOpen: false };
  let checked = 0;
  for (let i = 1; i < 200; i++) {
    const base = deco.listTraceHtml(topics[i], i, -1).html;
    if (!base.startsWith('<div class="cx-runline">')) continue;
    // 从 HTML 里认出用的是哪一款（RUIN_LINES 的文案是唯一的）
    const hit = deco.RUN_LINES.findIndex(([, text]) => base.includes(">" + text) || base.includes(text));
    if (hit < 0) continue;
    const avoided = deco.listTraceHtml(topics[i], i, hit).html;
    ok(`avoidRun 避开同款（行 ${i}）`, avoided !== base, { base, avoided, hit });
    checked++;
    if (checked >= 5) break;
  }
  ok("avoidRun 至少验证到几处", checked > 0, checked);
}

{
  // 思考块 HTML：展开与否由调用方传，两种状态都能折叠
  SET = { decorations: true, listTraceRate: 100, listThinkingOpen: false, detailThinkingOpen: true };
  const closed = deco.thinkingHtml(deco.thinkSentences, false);
  ok("thinkingHtml 关：class 无 open", closed.startsWith('<div class="cx-think">'), closed.slice(0, 40));
  ok("thinkingHtml 关：仍带可点的标题行与正文", closed.includes("cx-think-head") && closed.includes("cx-think-body"));
  ok("thinkingHtml 关：标题行有 Worked for Ns", /Worked for \d+s/.test(closed));

  // listThinkingOpen 要真的传到 thinkingHtml 上
  SET = { decorations: true, listTraceRate: 100, listThinkingOpen: true };
  (() => {
    let seen = 0;
    for (let i = 1; i < 120 && seen < 3; i++) {
      const html = deco.listTraceHtml(topics[i], i, -1).html;
      if (!html.startsWith('<div class="cx-think')) continue;
      ok("listThinkingOpen=true → 列表思考块默认展开", html.startsWith('<div class="cx-think open">'), html.slice(0, 40));
      seen++;
    }
    ok("列表里有思考块可查", seen > 0, seen);
  })();

  SET = { decorations: true, listTraceRate: 100, listThinkingOpen: false };
  (() => {
    let seen = 0;
    for (let i = 1; i < 120 && seen < 3; i++) {
      const html = deco.listTraceHtml(topics[i], i, -1).html;
      if (!html.startsWith('<div class="cx-think')) continue;
      ok("listThinkingOpen=false → 列表思考块默认收起", html.startsWith('<div class="cx-think">'), html.slice(0, 40));
      seen++;
    }
    ok("列表里有思考块可查（收起档）", seen > 0, seen);
  })();
}

{
  // 工具调用行的 HTML：图标 / 命令 / 重连计数三态
  const rnd = () => 0; // 恒取第 0 项
  const withIcon = deco.runlineHtmlFor(0, rnd);   // terminal + Running command + cmd
  ok("runline 带图标", withIcon.includes("[i:terminal]"), withIcon);
  ok("runline 带命令", withIcon.includes("<code>"), withIcon);
  const noCmd = deco.runlineHtmlFor(1, rnd);      // file + Reading file
  ok("runline 无命令", noCmd.includes("[i:file]") && !noCmd.includes("<code>"), noCmd);
  const reconnect = deco.runlineHtmlFor(7, rnd);  // [null, "Reconnecting"]
  ok("Reconnecting 带 N/M 计数", /Reconnecting \d+\/\d+/.test(reconnect), reconnect);
  ok("Reconnecting 不带图标标签", !/\[i:/.test(reconnect), reconnect);
  ok("runline 根节点 class 正确", withIcon.startsWith('<div class="cx-runline">'), withIcon);
}

/* ============ 3. SETTING_SPEC 与 DEFAULTS 一致 ============ */
{
  const { api } = loadCore(makeStore());
  const specSrc = slice("  const SETTING_CSS_VAR = {", "  function specItem(key) {");
  const spec = new Function("CODE_LANGS", "CODE_LANG_NAMES", specSrc + "\nreturn SETTING_SPEC;")(
    { rust: {}, python: {}, typescript: {}, go: {}, java: {} },
    { rust: "Rust", python: "Python", typescript: "TypeScript", go: "Go", java: "Java" });
  const items = spec.flatMap((g) => g.items.map((it) => ({ ...it, section: g.section })));
  const keys = items.map((it) => it.key);

  ok("面板覆盖全部 DEFAULTS 字段", Object.keys(api.DEFAULTS).every((k) => keys.includes(k)),
    Object.keys(api.DEFAULTS).filter((k) => !keys.includes(k)));
  ok("面板没有多余项", keys.every((k) => k in api.DEFAULTS), keys.filter((k) => !(k in api.DEFAULTS)));
  ok("key 不重复", new Set(keys).size === keys.length);

  for (const it of items) {
    const def = api.DEFAULTS[it.key];
    if (it.type === "range") ok(`range ${it.key} 默认值在区间内`, def >= it.min && def <= it.max, { def, min: it.min, max: it.max });
    else if (it.type === "select") {
      const opts = typeof it.options === "function" ? it.options() : it.options;
      ok(`select ${it.key} 含默认选项`, opts.some(([v]) => String(v) === String(def)), { def });
    } else if (it.type === "toggle") ok(`toggle ${it.key} 默认布尔`, typeof def === "boolean", def);
    ok(`${it.key} 有 label`, typeof it.label === "string" && it.label.length > 0);
  }
  // 装饰那一节要真的把三个关键开关摆出来
  const decorItems = items.filter((it) => it.section === "装饰").map((it) => it.key);
  ok("装饰节含列表痕迹密度 / 列表思考块 / 楼内思考块",
    ["listTraceRate", "listThinkingOpen", "detailThinkingOpen"].every((k) => decorItems.includes(k)), decorItems);
  const pw = items.find((it) => it.key === "panelWidth");
  ok("panelWidth 的 0 显示为自动", pw.format(0) === "自动" && pw.format(520) === "520px");
  const theme = items.find((it) => it.key === "theme");
  ok("主题三态齐全", ["auto", "dark", "light"].every((v) => theme.options.some(([o]) => o === v)));
}

/* ============ 4. CSS 完整性 ============ */
{
  const rawStart = "  const RAW_CSS = String.raw`";
  const a = SRC.indexOf(rawStart) + rawStart.length;
  const b = SRC.indexOf("\n  `;", a);
  const RAW_CSS = new Function("ROOT_CLASS", "LOCK_CLASS", "RAIL_WIDTH",
    "return String.raw`" + SRC.slice(a, b) + "`;")("codex-theme", "codex-locked", 306);

  const selStart = SRC.indexOf("  const PAGE_LAYER_SELECTOR = [");
  const selEnd = SRC.indexOf("].join(\", \");", selStart) + "].join(\", \");".length;
  const PLS = new Function(SRC.slice(selStart, selEnd) + "\nreturn PAGE_LAYER_SELECTOR;")();
  const pageLayerRules = PLS.split(",").map((s) => s.trim()).filter(Boolean)
    .map((s) => `html.codex-theme.codex-page-dim ${s}`).join(",\n    ");
  const css = RAW_CSS.replace(/PAGE_LAYER_LIST\s*\{/, () => pageLayerRules + " {");

  ok("占位符替换干净", !css.includes("PAGE_LAYER_LIST"));
  ok("页面层两条选择器展开", css.replace(/\s+/g, " ").includes(
    "html.codex-theme.codex-page-dim .codex-rail, html.codex-theme.codex-page-dim .codex-main {"));
  ok("RAW_CSS 里占位符只出现一次", (RAW_CSS.match(/PAGE_LAYER_LIST\s*\{/g) || []).length === 1);
  ok("正文宽度走变量", css.includes("max-width: var(--cx-thread-max, 760px)"));
  ok("正文宽度 token 已定义", /--cx-thread-max: 760px;/.test(css));

  const lightBlock = css.slice(css.indexOf("Token：浅色"), css.indexOf("/* ---------- 自绘 UI 统一盒模型"));
  ok("浅色块含字体 token（原孤儿声明已归位）", lightBlock.includes("--cx-font-ui") && lightBlock.includes("--cx-radius: 10px;"));
  const lastBrace = lightBlock.lastIndexOf("}");
  ok("浅色块之后没有裸声明", lightBlock.slice(lastBrace + 1).trim() === "", lightBlock.slice(lastBrace + 1).trim().slice(0, 60));

  for (const cls of [".cx-modal {", ".cx-switch.on > span", ".cx-range {", ".cx-select,", ".cx-text {",
    ".cx-thread-rows .cx-think,", ".cx-thread-rows .cx-runline {"]) {
    ok(`样式存在 ${cls}`, css.includes(cls));
  }
  const stripped = css.replace(/\/\*[\s\S]*?\*\//g, "");
  ok("CSS 大括号平衡",
    (stripped.match(/\{/g) || []).length === (stripped.match(/\}/g) || []).length,
    { open: (stripped.match(/\{/g) || []).length, close: (stripped.match(/\}/g) || []).length });
}

console.log(`\n通过 ${pass} 项，失败 ${fails.length} 项`);
if (fails.length) {
  console.log("\n失败明细：");
  for (const f of fails) console.log("  ✗ " + f);
  process.exit(1);
